import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.C-si7TFR.js";const u=JSON.parse('{"title":"周期任务触发器","description":"如何创建一个定时任务，每月、每周、每天、每小时触发工作流执行。","frontmatter":{"title":"周期任务触发器","description":"如何创建一个定时任务，每月、每周、每天、每小时触发工作流执行。","meta":[{"name":"keywords","content":"定时任务, 周期任务, 定时工具, Crontab定时任务, Cron定时任务, Linux定时任务, Windows定时任务, Linux Crontab, 低代码, AI工作流, 流程引擎"}]},"headers":[],"relativePath":"zh/trigger_crontab.md","filePath":"zh/trigger_crontab.md"}'),o={name:"zh/trigger_crontab.md"};function l(i,t,n,c,h,p){return r(),a("div",null,[...t[0]||(t[0]=[e('<h2 id="周期任务触发器" tabindex="-1">周期任务触发器 <a class="header-anchor" href="#周期任务触发器" aria-label="Permalink to &quot;周期任务触发器&quot;">​</a></h2><p>可设置周期性运行的工作流，支持分钟、小时、天、周和月，语法格式跟Linux系统的crontab一样。</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><p>创建的工作流可以在【流程管理】下的【工作流列表】或【Crontab列表】找到：</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h2 id="入参" tabindex="-1">入参 <a class="header-anchor" href="#入参" aria-label="Permalink to &quot;入参&quot;">​</a></h2><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h3 id="周期表达式" tabindex="-1">周期表达式 <a class="header-anchor" href="#周期表达式" aria-label="Permalink to &quot;周期表达式&quot;">​</a></h3><p>五个字段分别表示如下：</p><blockquote><ul><li>分钟：0-59。注意分钟级的任务，执行的秒时刻会随机固定某个时刻，不一定是每分钟的0秒时刻，例如每分钟的第3秒等，但是运行周期是间隔一分钟。</li><li>小时：1-23</li><li>日：1-31</li><li>月：1-12</li><li>周：0-6（0表示周日）</li></ul></blockquote><p>还有一些其他特殊的字符</p><blockquote><ul><li>*：表示任意时刻</li><li>,：表示多个，例如：0 2,4 * * *，表示每天的2点和4点钟整运行</li><li>－：表示范围，例如：0 1-5 * * *，表示每天的1点到5点整，即1、2、3、4、5点整运行</li><li>/n : 表示每隔多少时间，例如：0 */2 * * *，表示每隔2小时运行</li></ul></blockquote><p>例子：</p><table tabindex="0"><thead><tr><th>表达式</th><th>说明</th></tr></thead><tbody><tr><td>*/10 * * * *</td><td>每隔10分钟运行</td></tr><tr><td>43 21 * * *</td><td>每天的21点43分运行</td></tr><tr><td>15 05 * * *</td><td>每天的5点15分运行</td></tr><tr><td>0 17 * * *</td><td>每天的17点运行</td></tr><tr><td>0 17 * * 1</td><td>每周一的17点运行</td></tr><tr><td>0,10 17 * * 0,2,3</td><td>每周日、周二、周三的17点10分运行</td></tr><tr><td>0-10 17 1 * *</td><td>每个月1号的17点0分到17点10分运行</td></tr><tr><td>42 4 1 * *</td><td>每个月1号的4点42分运行</td></tr><tr><td>0 21 * * 1-6</td><td>每周一至周六的21点0分运行</td></tr><tr><td>0,10,20,30,40,50 * * * *</td><td>每小时的0、10、20、30、40、50分的时候运行</td></tr><tr><td>*/10 * * * *</td><td>每隔10分钟运行，跟上面相等</td></tr><tr><td>* 1 * * *</td><td>每天1点内每分钟运行（00分到59分）</td></tr><tr><td>0 1 * * *</td><td>每天的1点钟运行</td></tr><tr><td>0 */1 * * *</td><td>每小时运行</td></tr><tr><td>0 * * * *</td><td>每小时运行</td></tr><tr><td>2 8-20/3 * * *</td><td>每天的8:02、11:02、14:02、17:02、20:02运行</td></tr><tr><td>30 5 1,15 * *</td><td>在每个月的1号和15号的5:30运行</td></tr></tbody></table><h3 id="是否允许多任务同时运行" tabindex="-1">是否允许多任务同时运行 <a class="header-anchor" href="#是否允许多任务同时运行" aria-label="Permalink to &quot;是否允许多任务同时运行&quot;">​</a></h3><p>如果勾选允许，则每个运行周到到达时，就会触发工作流运行，不管前面有没有运行中的工作流未跑完。</p><p>如果不勾选，则每个运行周期到达时，系统会检测前面有没有运行中的工作流未结束。如果有，则不运行，如果没有，则运行。例如创建了一个每分钟的工作流任务，有可能某个任务执行时间超过1分钟，这时候就需要用到这个逻辑来去重。</p><h2 id="出参" tabindex="-1">出参 <a class="header-anchor" href="#出参" aria-label="Permalink to &quot;出参&quot;">​</a></h2><p>无</p>',19)])])}const s=d(o,[["render",l]]);export{u as __pageData,s as default};
